var currentLang = "en";
function hasLang(lang) { return Object.prototype.hasOwnProperty.call(DICT, lang); }
function detectBrowserLang() { var list = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || "en"]); for (var i = 0; i < list.length; i++) { var code = String(list[i] || "").toLowerCase().split("-")[0]; if (hasLang(code)) { return code; } } return "en"; }
function t(key, fallback) { var langDict = DICT[currentLang] || DICT.en; return (langDict && langDict[key]) || DICT.en[key] || fallback || key; }
function applyTranslations() { document.documentElement.setAttribute("lang", currentLang); var nodes = document.querySelectorAll("[data-i18n]"); for (var i = 0; i < nodes.length; i++) { var node = nodes[i]; var key = node.getAttribute("data-i18n"); node.textContent = t(key, node.textContent); } var placeholders = document.querySelectorAll("[data-i18n-placeholder]"); for (var j = 0; j < placeholders.length; j++) { var p = placeholders[j]; p.setAttribute("placeholder", t(p.getAttribute("data-i18n-placeholder"), p.getAttribute("placeholder"))); } var titles = document.querySelectorAll("[data-i18n-title]"); for (var k = 0; k < titles.length; k++) { var n = titles[k]; n.setAttribute("title", t(n.getAttribute("data-i18n-title"), n.getAttribute("title"))); } document.dispatchEvent(new CustomEvent("cw:lang-changed", { detail: { lang: currentLang } })); }
function getLanguageSelects() { return document.querySelectorAll("select#cw-lang-select, .lang-switcher select"); }
function setLang(lang, persist) { var next = hasLang(lang) ? lang : "en"; currentLang = next; if (persist) { localStorage.setItem(STORAGE_KEY, next); localStorage.setItem(PROMPTED_KEY, "1"); } applyTranslations(); var selects = getLanguageSelects(); for (var i = 0; i < selects.length; i++) { if (selects[i].value !== next) { selects[i].value = next; } } }
function ensureSwitcher() { var selects = getLanguageSelects(); for (var i = 0; i < selects.length; i++) { var select = selects[i]; if (!select || select.getAttribute("data-ready") === "1") { continue; } select.innerHTML = ""; Object.keys(LANG_META).forEach(function (lang) { var option = document.createElement("option"); option.value = lang; option.textContent = LANG_META[lang].label; select.appendChild(option); }); select.value = currentLang; select.addEventListener("change", function () { setLang(this.value, true); }); select.setAttribute("data-ready", "1"); } }
function maybePromptDetectedLanguage() { var saved = localStorage.getItem(STORAGE_KEY); if (saved) { return; } if (localStorage.getItem(PROMPTED_KEY) === "1") { return; } var detected = detectBrowserLang(); if (detected === "en" || !hasLang(detected)) { localStorage.setItem(PROMPTED_KEY, "1"); return; } var accepted = window.confirm(t("lang.prompt." + detected, "Switch language?")); if (accepted) { setLang(detected, true); } else { setLang("en", true); } }
function init() { var saved = localStorage.getItem(STORAGE_KEY); setLang(saved && hasLang(saved) ? saved : "en", false); applyTranslations(); maybePromptDetectedLanguage();
